    request_uri, http_method, client_ip, device_type_cd, device_os, device_browser, device_model,
    user_agent, session_id, fail_reason, access_dt, reg_id
) VALUES (
    #{userId}, #{userNm}, #{accessTypeCd}, #{loginTypeCd}, #{successYn},
    #{requestUri}, #{httpMethod}, #{clientIp}, #{deviceTypeCd}, #{deviceOs}, #{deviceBrowser}, #{deviceModel},
    #{userAgent}, #{sessionId}, #{failReason}, COALESCE(#{accessDt}, CURRENT_TIMESTAMP), #{regId}
