mapper.select:
SELECT 
FROM user_access_log
WHERE user_id = #{userId}
ORDER BY access_dt DESC
LIMIT #{limit}

SELECT 
FROM user_access_log
WHERE access_dt >= #{rangeStart}
  AND access_dt < #{rangeEnd}
ORDER BY access_dt DESC
LIMIT #{limit}

SELECT 
FROM user_access_log


        AND user_id LIKE CONCAT('%', #{userId}, '%')


        AND client_ip LIKE CONCAT('%', #{clientIp}, '%')


        AND access_type_cd = #{accessTypeCd}


        AND login_type_cd = #{loginTypeCd}


        AND success_yn = #{successYn}


        AND access_dt >= #{rangeStart}


        AND access_dt < #{rangeEnd}


ORDER BY access_dt DESC
LIMIT #{limit}
